from fractions import Fraction as F
import json

# Search linear candidates f(x)=a*x+b over an exact rational grid and test
# the functional equation on a grid of (x, y) values.
vals = [F(k, 2) for k in range(-10, 11)]
pts = [F(k, 3) for k in range(-6, 7)]

sols = []
for a in vals:
    for b in vals:
        f = lambda t: a * t + b
        ok = all(
            f(x) * f(x + y) == f(2 * x + y) - x * f(x + y) + x
            for x in pts for y in pts
        )
        if ok:
            sols.append((a, b))

# Injective linear functions need a != 0
inj = [(a, b) for a, b in sols if a != 0]

if len(inj) == 1:
    a, b = inj[0]
    def show(c):
        return str(c)
    if a == -1 and b == 1:
        ans = "f(x) = 1 - x"
    else:
        ans = f"f(x) = {show(a)}*x + {show(b)}"
    print(json.dumps({
        "final_answer": ans,
        "evidence": {
            "all_linear_solutions": [[str(a), str(b)] for a, b in sols],
            "injective_solutions": [[str(a), str(b)] for a, b in inj],
            "grid": "a,b in half-integers [-5,5]; x,y in thirds [-2,2]"
        }
    }))
else:
    print("UNSUPPORTED")
