import math

def lhs(x):
    r = math.radians
    return 4*math.sin(x)*math.sin(r(60)-x)*math.sin(r(60)+x)

def sub(x):
    return math.sin(x)*(2*math.cos(2*x)+1)

def target(x):
    return math.sin(3*x)

pts = [2*math.pi*(k+0.37)/23 for k in range(23)]  # 23 distinct points in [0, 2pi)
max_sub = max(abs(lhs(x)-sub(x)) for x in pts)
max_tgt = max(abs(lhs(x)-target(x)) for x in pts)
print("max |LHS - submitted| over 23 points:", max_sub)
print("max |LHS - sin(3x)| over 23 points:", max_tgt)

# Both sides are trig polynomials of degree <= 3, so the difference has at most 6 zeros
# in [0, 2pi) unless identically zero. 23 agreeing points therefore prove the identity.
# Algebraic confirmation: sin x (2cos2x+1) = sin x (3 - 4 sin^2 x) = sin 3x.
s_ok = all(abs(sub(x) - (3*math.sin(x) - 4*math.sin(x)**3)) < 1e-12 for x in pts)
print("submitted == 3 sin x - 4 sin^3 x (= sin 3x):", s_ok)

if max_sub < 1e-12 and s_ok:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
